<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { AlertTriangle, List, MapPinned, Search, Truck } from 'lucide-vue-next';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { label, params, stale, stamp, useMonitoringOptions, useResponsiveDrawer } from '../province-monitoring';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ProvinceMonitoringMap from '../components/ProvinceMonitoringMap.vue';
import ProvinceVehicleDrawer from '../components/ProvinceVehicleDrawer.vue';
import ProvincePageState from '../components/ProvincePageState.vue';
import '../province-monitoring.css';
const route = useRoute(), router = useRouter(), session = useSessionStore(), { options, loadOptions } = useMonitoringOptions();
const permission = (p: string) => session.user?.permissions.includes(p);
const alertWidth = useResponsiveDrawer(580);
const alertsMode = computed(() => route.query.view === 'alerts'), q = ref(''), workspaceId = ref(''), enterpriseId = ref(''), drivingState = ref(''), riskLevel = ref(''), alertStatus = ref(''), page = ref(1), bucket = ref('ALL'), layout = ref('split');
const occurrenceDates = ref<[string,string] | null>(null);
const rows = ref<any[]>([]), total = ref(0), counts = ref<Record<string, number>>({}), mapPoints = ref<any[]>([]), mapTruncated = ref(false), selectedId = ref(''), loading = ref(false), error = ref(''), updateError = ref(''), updatedAt = ref(''), vehicleDrawer = ref(false), vehicleId = ref(''), vehicleTab = ref('overview'), alertDrawer = ref(false), alert = ref<any>(), mapRef = ref<InstanceType<typeof ProvinceMonitoringMap>>();
const enterprises = computed(() => options.value.enterprises.filter(e => !workspaceId.value || e.workspaceId === workspaceId.value));
let generation = 0, controller: AbortController | undefined, disposed = false, lastRead = 0;
function values() { return { q: q.value.trim(), workspaceId: workspaceId.value, enterpriseId: enterpriseId.value, drivingState: drivingState.value, riskLevel: riskLevel.value, alertStatus: alertStatus.value, page: page.value, ...(alertsMode.value ? { view: 'alerts', from: occurrenceDates.value?.[0], to: occurrenceDates.value?.[1] } : { bucket: bucket.value, layout: layout.value }) }; }
async function load(background = false) {
  const current = ++generation; controller?.abort(); controller = new AbortController(); if (!background) loading.value = true; error.value = ''; updateError.value = ''; lastRead = Date.now();
  try { if (!options.value.workspaces.length) await loadOptions(); const result = await api<any>(`/province/${alertsMode.value ? 'alerts' : 'monitoring'}?${params({ ...values(), view: undefined, layout: undefined })}`, { signal: controller.signal }); if (current !== generation || disposed) return; rows.value = result.items; total.value = result.total; counts.value = result.counts ?? {}; mapPoints.value = result.mapPoints ?? []; mapTruncated.value = result.mapTruncated; updatedAt.value = result.updatedAt ?? new Date().toISOString(); if (!mapPoints.value.some(p => p.id === selectedId.value)) selectedId.value = ''; }
  catch (reason) { if (current === generation && !controller.signal.aborted) { const message = reason instanceof Error ? reason.message : '运行监测读取失败'; if (background && rows.value.length) updateError.value = message; else error.value = message; } }
  finally { if (current === generation) loading.value = false; }
}
function search(reset = true) { if (reset) page.value = 1; const query = Object.fromEntries(Object.entries(values()).filter(([, v]) => v !== '' && v != null).map(([k, v]) => [k, String(v)])); if (router.resolve({ path: '/province/monitoring', query }).fullPath === route.fullPath) void load(); else void router.replace({ path: '/province/monitoring', query }); }
function reset() { q.value = workspaceId.value = enterpriseId.value = drivingState.value = riskLevel.value = alertStatus.value = ''; occurrenceDates.value=null; bucket.value = 'ALL'; search(); }
function choose(id: string) { selectedId.value = id; void nextTick(() => mapRef.value?.focus(id)); }
function vehicleRowClass({ row }: { row: { id: string; riskCount?: number | null } }) { return [(row.riskCount ?? 0) > 0 ? 'pm-alert-row' : '', row.id === selectedId.value ? 'pm-selected-row' : ''].filter(Boolean).join(' '); }
function dossier(id: string, tab = 'overview') { vehicleId.value = id; vehicleTab.value = tab; vehicleDrawer.value = true; }
function mapAction(kind: string, id: string) {
  if (kind !== 'track') { dossier(id); return; }
  const row = mapPoints.value.find(row => row.id === id); if (row) void router.push({ path: '/province/cockpit', query: { cityCode: row.cityCode, enterpriseId: row.enterpriseId, organizationId: row.organizationId, vehicleId: id, mapMode: 'vehicles' } });
}
async function openAlert(row: any) { alert.value = row; alertDrawer.value = true; }
function notice() { if (!alert.value) return; void router.push({ path: '/province/coordination', query: { kind: 'RISK_NOTICE', relatedType: 'ALERT', relatedId: alert.value.id, create: '1', title: alert.value.title, basis: alert.value.businessNo, workspaceId: alert.value.workspaceId, level: alert.value.level, description: alert.value.description ?? '请属地核查风险情况并反馈处置措施。' } }); }
watch(() => route.query, async query => {
  occurrenceDates.value=typeof query.from==='string'&&typeof query.to==='string'?[query.from,query.to]:null;
  q.value = String(query.q ?? ''); workspaceId.value = String(query.workspaceId ?? ''); enterpriseId.value = String(query.enterpriseId ?? ''); drivingState.value = String(query.drivingState ?? ''); riskLevel.value = String(query.riskLevel ?? query.level ?? ''); alertStatus.value = String(query.alertStatus ?? ''); page.value = Math.max(1, Number(query.page) || 1); bucket.value = ['ALL', 'RUNNING', 'OFFLINE', 'ALERT'].includes(String(query.bucket)) ? String(query.bucket) : 'ALL'; layout.value = ['split', 'list', 'map'].includes(String(query.layout)) ? String(query.layout) : 'split';
  await load(); const alertId = query.alertId ?? query.entityId; if (alertsMode.value && typeof alertId === 'string') { const found = rows.value.find(row => row.id === alertId); if (found) void openAlert(found); else try { const result = await api<any>(`/province/alerts/${encodeURIComponent(alertId)}?${params({ workspaceId: workspaceId.value })}`); if (!disposed) void openAlert(result); } catch (reason) { error.value = reason instanceof Error ? reason.message : '告警读取失败'; } }
}, { immediate: true });
const timer = setInterval(() => { if (!disposed && !document.hidden && !loading.value && !alertDrawer.value && !vehicleDrawer.value && Date.now() - lastRead > 30000) void load(true); }, 1000);
onBeforeUnmount(() => { disposed = true; generation++; controller?.abort(); clearInterval(timer); });
</script>
<template><section class="pm-page pm-fill-page"><h1 class="sr-only">运行监测</h1><QueryPanel :loading="loading" @search="search()" @reset="reset"><QueryField label="地市"><el-select v-model="workspaceId" aria-label="地市" clearable placeholder="全部地市" @change="enterpriseId = ''; search()"><el-option v-for="city in options.workspaces" :key="city.id" :label="city.cityName" :value="city.id"/></el-select></QueryField><QueryField label="运营企业"><el-select v-model="enterpriseId" aria-label="运营企业" clearable filterable placeholder="全部企业"><el-option v-for="company in enterprises" :key="company.id" :label="company.name" :value="company.id"/></el-select></QueryField><QueryField :label="alertsMode ? '告警 / 车辆' : '车辆编号'" keyword><el-input v-model="q" :aria-label="alertsMode ? '告警关键词' : '车辆编号'" :prefix-icon="Search" clearable :placeholder="alertsMode ? '告警编号、标题或车辆编号' : '编号 / 统一编码 / VIN'"/></QueryField><QueryField v-if="!alertsMode" label="运行状态"><el-select v-model="drivingState" aria-label="运行状态" clearable placeholder="全部状态"><el-option v-for="state in ['RUNNING','IDLE','PARKED']" :key="state" :value="state" :label="label(state)"/></el-select></QueryField><QueryField v-if="permission('safety:alert:read')" label="风险等级"><el-select v-model="riskLevel" aria-label="风险等级" clearable placeholder="全部等级"><el-option v-for="level in ['LOW','MEDIUM','HIGH','CRITICAL']" :key="level" :value="level" :label="label(level)"/></el-select></QueryField><QueryField v-if="alertsMode" label="处理状态"><el-select v-model="alertStatus" aria-label="处理状态" clearable placeholder="全部状态"><el-option label="全部状态" value="ALL"/><el-option label="处置中（汇总）" value="HANDLING"/><el-option v-for="state in ['PENDING_CONFIRMATION','PENDING_HANDLING','IN_PROGRESS','PENDING_REVIEW','CLOSED']" :key="state" :value="state" :label="label(state)"/></el-select></QueryField></QueryPanel><div v-if="alertsMode && occurrenceDates" class="pm-toolbar"><el-tag closable @close="occurrenceDates=null;search()">发生日期：{{occurrenceDates[0]}} 至 {{occurrenceDates[1]}}</el-tag></div>
<div class="pm-toolbar"><div v-if="!alertsMode" class="pm-buckets"><button v-for="[key, name] in [['ALL','全部车辆'],['RUNNING','运行中'],['OFFLINE','离线异常'],...(permission('safety:alert:read') ? [['ALERT','存在待处理告警']] : [])]" :key="key" type="button" :aria-pressed="bucket === key" @click="bucket = key!; search()">{{ name }}<b v-if="counts[key!] != null">{{ counts[key!] }}</b></button></div><span v-else class="pm-view-label"><AlertTriangle :size="16"/>全部告警 · 包含未关联车辆的记录</span><div class="pm-toolbar-actions"><el-button v-if="alertsMode && permission('operation:realtime:read')" @click="router.push('/province/monitoring')">返回车辆监测</el-button><el-button v-else-if="permission('safety:alert:read')" @click="router.push({ path: '/province/monitoring', query: { view: 'alerts', ...(workspaceId ? { workspaceId } : {}) } })">全部告警</el-button><el-radio-group v-if="!alertsMode" v-model="layout" aria-label="监测显示方式" @change="search(false)"><el-radio-button value="split"><MapPinned :size="14"/>联动</el-radio-button><el-radio-button value="list"><List :size="14"/>列表</el-radio-button><el-radio-button value="map"><MapPinned :size="14"/>地图</el-radio-button></el-radio-group></div></div>
<el-alert v-if="updateError" :title="`自动更新失败，保留上次数据：${updateError}`" type="warning" :closable="false"/><ProvincePageState class="pm-fill-body" :error="error" :loading="loading" @retry="load()"><div v-if="!alertsMode" class="pm-monitor-workspace" :class="`layout-${layout}`"><section v-if="layout !== 'map'" class="pm-list-surface" aria-label="车辆运行列表"><el-table :data="rows" height="100%" row-key="id" :row-class-name="vehicleRowClass" @row-click="(row: any) => choose(row.id)"><el-table-column v-if="permission('safety:alert:read')" type="expand" width="32"><template #default="{ row }"><div class="pm-expanded-alerts"><p v-if="!row.safetyAlerts?.length">该车暂无待处理告警</p><div v-for="event in row.safetyAlerts" :key="event.id"><AlertTriangle :size="14"/><strong>{{ event.title }}</strong><span>{{ label(event.status) }}</span><time>{{ stamp(event.occurredAt) }}</time><el-button link type="primary" @click.stop="openAlert({ ...event, vehicle: row, enterprise: row.enterprise, cityName: row.cityName, workspaceId: row.workspaceId })">查看告警</el-button></div><el-button v-if="row.riskCount > 3" link type="primary" @click.stop="dossier(row.id, 'alerts')">查看该车全部 {{ row.riskCount }} 条告警</el-button></div></template></el-table-column><el-table-column label="车辆 / 企业" min-width="185"><template #default="{ row }"><el-button class="pm-vehicle-link" type="primary" link :disabled="!permission('archive:vehicle:read')" @click.stop="dossier(row.id)">{{ row.businessNo }}</el-button><small class="pm-subline">{{ row.enterprise.name }}</small></template></el-table-column><el-table-column prop="cityName" label="所属地市" width="86"/><el-table-column label="运行状态" width="110"><template #default="{ row }"><span class="pm-status" :class="row.onlineStatus === 'ONLINE' ? 'online' : 'offline'"><i/>{{ row.onlineStatus === 'OFFLINE' ? '离线' : label(row.realtimeStatus?.drivingState) }}</span><small v-if="row.onlineStatus === 'ONLINE' && stale(row)" class="pm-stale">上报已超10分钟</small></template></el-table-column><el-table-column v-if="permission('safety:alert:read')" label="风险情况" min-width="130"><template #default="{ row }"><el-tag :type="row.riskCount ? 'warning' : 'info'" effect="plain" size="small">{{ row.riskCount ? `待处理告警 · ${row.riskCount}条` : '暂无待处理告警' }}</el-tag></template></el-table-column><el-table-column label="最后上报" width="120"><template #default="{ row }">{{ stamp(row.realtimeStatus?.heartbeatAt) }}</template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="{ row }"><el-button link type="primary" :disabled="!row.realtimeStatus" @click.stop="layout = 'split'; choose(row.id)">定位</el-button><el-button v-if="permission('archive:vehicle:read')" link type="primary" @click.stop="dossier(row.id)">档案</el-button></template></el-table-column></el-table></section><aside v-if="layout !== 'list'" class="pm-monitor-map" aria-label="地图联动"><ProvinceMonitoringMap ref="mapRef" :points="mapPoints" :selected-id="selectedId" height="100%" @select="selectedId = $event" @action="mapAction"/><p v-if="mapTruncated" class="pm-map-limit">地图仅展示前5000辆，请缩小筛选范围</p></aside></div>
<section v-else class="pm-list-surface"><el-table :data="rows" height="100%" empty-text="没有符合条件的风险告警"><el-table-column label="风险事项" min-width="250"><template #default="{ row }"><strong>{{ row.title }}</strong><small class="pm-subline">{{ row.businessNo }}</small></template></el-table-column><el-table-column prop="cityName" label="所属地市" width="110"/><el-table-column label="车辆 / 企业" min-width="210"><template #default="{ row }"><span>{{ row.vehicle?.businessNo || '未关联车辆' }}</span><small class="pm-subline">{{ row.enterprise?.name }}</small></template></el-table-column><el-table-column label="等级" width="90"><template #default="{ row }"><el-tag :type="['CRITICAL','HIGH'].includes(row.level) ? 'danger' : 'warning'" effect="plain">{{ label(row.level) }}</el-tag></template></el-table-column><el-table-column label="处理状态" width="115"><template #default="{ row }">{{ label(row.status) }}</template></el-table-column><el-table-column label="发生时间" width="145"><template #default="{ row }">{{ stamp(row.occurredAt) }}</template></el-table-column><el-table-column label="操作" width="170"><template #default="{ row }"><el-button type="primary" link @click="openAlert(row)">查看告警</el-button><el-button v-if="row.vehicle && permission('archive:vehicle:read')" type="primary" link @click="dossier(row.vehicle.id, 'alerts')">车辆档案</el-button></template></el-table-column></el-table></section><footer class="pm-pagination"><span>共 {{ total }} {{ alertsMode ? '条告警' : '辆车辆' }}<small>更新于 {{ stamp(updatedAt) }} · 上报状态以最后心跳为准</small></span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="search(false)"/></footer></ProvincePageState>
<ProvinceVehicleDrawer v-model="vehicleDrawer" :vehicle-id="vehicleId" :workspace-id="workspaceId" :initial-tab="vehicleTab"/>
<el-drawer v-model="alertDrawer" class="pm-drawer" title="风险告警" :size="alertWidth"><template v-if="alert"><h2>{{ alert.title }}</h2><p class="pm-muted">{{ alert.businessNo }} · {{ stamp(alert.occurredAt) }}</p><dl class="pm-facts"><div><dt>风险等级</dt><dd>{{ label(alert.level) }}</dd></div><div><dt>当前状态</dt><dd>{{ label(alert.status) }}</dd></div><div><dt>所属地市</dt><dd>{{ alert.cityName || '—' }}</dd></div><div><dt>关联车辆</dt><dd>{{ alert.vehicle?.businessNo || '未关联车辆' }}</dd></div><div><dt>运营企业</dt><dd>{{ alert.enterprise?.name || '—' }}</dd></div><div><dt>发生地点</dt><dd>{{ alert.address || '—' }}</dd></div></dl><section class="pm-detail-card"><h3>风险说明</h3><p>{{ alert.description || '暂无补充说明' }}</p></section><section class="pm-detail-card"><h3>最近处理进展</h3><p>{{ alert.lastComment || '尚无处理记录' }}</p></section></template><template #footer><el-button v-if="alert?.vehicle && permission('archive:vehicle:read')" @click="alertDrawer = false; dossier(alert.vehicle.id, 'alerts')">查看车辆档案</el-button><el-button v-if="permission('system:organization:update') && alert?.status !== 'CLOSED'" type="primary" @click="notice">发起风险通报</el-button></template></el-drawer>
</section></template>



